Aquí está un ejemplo de código para un bot de Discord que utiliza el paquete `discord.js` v14 y un comando de barra diagonal `ban`:

1. Primero, instala los paquetes necesarios:

```bash
npm install discord.js dotenv
```

2. Crea un archivo `.env` en la raíz de tu proyecto y agrega la siguiente información de configuración:

```dotenv
DISCORD_CLIENT_ID=[Tu ID de cliente de Discord]
DISCORD_CLIENT_SECRET=[Tu secreto de cliente de Discord]
DISCORD_BOT_TOKEN=[Tu token de bot de Discord]
```

3. Crea un nuevo archivo de JavaScript, por ejemplo, `bot.js`, y agrega el siguiente código:

```javascript
const { Client, GatewayIntentBits, Events, Collection } = require('discord.js');
const fs = require('node:fs');
require('dotenv').config();

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.commands = new Collection();

const commandFiles = fs
  .readdirSync('./commands')
  .filter((file) => file.endsWith('.js'));

for (const file of commandFiles) {
  const command = require(`./commands/${file}`);
  client.commands.set(command.data.name, command);
}

client.on(Events.InteractionCreate, async (interaction) => {
  if (!interaction.isCommand()) return;

  const command = client.commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'Ha ocurrido un error al ejecutar este comando.', ephemeral: true });
  }
});

client.on(Events.MessageCreate, (message) => {
  if (message.author.bot || !message.content.startsWith(process.env.PREFIX)) return;

  const args = message.content.slice(process.env.PREFIX.length).trim().split(' ');
  const commandName = args.shift().toLowerCase();

  const command =
    client.commands.get(commandName) ||
    client.commands.find((command) => command.aliases && command.aliases.includes(commandName));

  if (!command) return;

  try {
    command.execute(message, ...args);
  } catch (error) {
    console.error(error);
    message.reply({ content: 'Ha ocurrido un error al ejecutar este comando.' });
  }
});

client.login(process.env.DISCORD_BOT_TOKEN);
```

4. Crea un directorio llamado `commands` en la raíz de tu proyecto, y dentro de este, crea un nuevo archivo llamado `ban.js`. Agrega el siguiente código:

```javascript
const { MessageEmbed, CommandInteraction, Message } = require('discord.js');
const { ban } = require('./utils');

module.exports = {
  data: new CommandInteraction().slashBuilder()
    .setName('ban')
    .setDescription('Banea a un miembro del servidor.'),

  async execute(interaction, args) {
    const member = interaction.options.getMember('miembro');

    if (!member) {
      return interaction.reply({ content: 'Por favor, proporciona un miembro válido para banear.', ephemeral: true });
    }

    if (member.permissions.has('ADMINISTRATOR') && !interaction.member.permissions.has('ADMINISTRATOR')) {
      return interaction.reply({ content: 'No tienes los permisos suficientes para banear a este miembro.', ephemeral: true });
    }

    await ban(interaction, member);

    const embed = new MessageEmbed()
      .setColor('#FF0000')
      .setTitle('Baneo')
      .setDescription(`**Miembro:** ${member.user.tag}\n**ID:** ${member.user.id}\n**Moderador:** ${interaction.user.tag}\n**Motivo:** (ninguno)`)
      .setTimestamp();

    interaction.reply({ embeds: [embed] });
  },
};
```

5. Crea un nuevo archivo llamado `ban.js` en el directorio `utils` y agrega el siguiente código:

```javascript
const { MessageEmbed, Message } = require('discord.js');

async function ban(interaction, member) {
  await member.ban({ reason: 'Baneo realizado por un moderador.' });

  const embed = new MessageEmbed()
    .setColor('#FF0000')
    .setTitle('Baneo')
    .setDescription(`**Miembro:** ${member.user.tag}\n**ID:** ${member.user.id}\n**Moderador:** ${interaction.user.tag}\n**Motivo:** Baneo realizado por un moderador.`)
    .setTimestamp();

  const channel = interaction.guild.channels.cache.find((ch) => ch.id === 'ID_DEL_CANAL_LOGS');
  if (channel) {
    channel.send({ embeds: [embed] });
  }

  await interaction.reply({ content: `${member.user.tag} ha sido baneado del servidor.`, ephemeral: true });
}
```

6. Configura tu bot de Discord, proporcionando los permisos adecuados para usar el comando `ban` y para enviar mensajes en el canal de logs.

7. Reemplaza `ID_DEL_CANAL_LOGS` por el ID de tu canal de logs. Si no tienes un canal de logs, puedes crear uno y configurarlo con el permiso `Enviar mensajes` para el bot.

8. Cambia el valor de la variable de entorno `PREFIX` en tu archivo `.env` para que coincida con tu prefijo de comando, por ejemplo, `!`.

9. Crea un nuevo directorio llamado `commands` en la raíz de tu proyecto, y dentro de este, crea un nuevo archivo llamado `index.js`. Agrega el siguiente código:

```javascript
module.exports = {
  name: 'ban',
};

module.exports = {
  name: 'ban',
  aliases: ['b'],
};
```

Estos archivos de configuración de comando son opcionales, pero te permiten agrupar tus comandos en un solo lugar para una organización más clara. Los comandos de barra diagonal no pueden tener alias, por lo que el segundo ejemplo solo se usa para el comando de comillas.

10. Agrega los archivos de comando a la carpeta `commands` de tu proyecto.

11. Ejecuta el bot con `node bot.js` en la consola.

12. Configura el bot de Discord para que esté en línea, proporcionando el token de bot de Discord en tu archivo `.env`.

¡Y eso es todo! Ahora puedes usar el comando `ban` en tu servidor de Discord, proporcionando el ID de un miembro para banearlo. Si no proporcionas un ID, el comando borrará al autor del mensaje. El bot también registrará el baneo en un canal de logs, si lo configuraste.

¡Recuerda que la seguridad es importante! Evita la ejecución de comandos de banear sin validación de permisos adecuados, y asegúrate de que los comandos de banear solo sean accesibles para los miembros con los permisos adecuados. Si no, podrías borrar accidentalmente a miembros de tu servidor.

